CREATE TABLE organizations(id text PRIMARY KEY,name text NOT NULL,loyalty_scope text NOT NULL DEFAULT 'restaurant' CHECK(loyalty_scope IN ('restaurant','organization')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','archived')),created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO organizations(id,name) VALUES('legacy','Établissements historiques');
ALTER TABLE restaurants ADD COLUMN organization_id text NOT NULL DEFAULT 'legacy' REFERENCES organizations;
CREATE INDEX restaurants_organization ON restaurants(organization_id,id);
ALTER TABLE profiles ADD COLUMN email text NOT NULL DEFAULT '',ADD COLUMN status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended'));
CREATE TABLE organization_memberships(organization_id text REFERENCES organizations,profile_id text REFERENCES profiles,role text NOT NULL CHECK(role IN ('OWNER','ADMIN','MEMBER')),PRIMARY KEY(organization_id,profile_id));
CREATE TABLE invitations(id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations,restaurant_id text NOT NULL REFERENCES restaurants,email text NOT NULL,roles jsonb NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,accepted_at timestamptz,created_by text NOT NULL REFERENCES profiles);
CREATE TABLE platform_admins(profile_id text PRIMARY KEY REFERENCES profiles);
CREATE TABLE support_grants(id text PRIMARY KEY,profile_id text REFERENCES profiles,restaurant_id text REFERENCES restaurants,reason text NOT NULL CHECK(length(reason)>=10),expires_at timestamptz NOT NULL,revoked_at timestamptz,approved_by text NOT NULL REFERENCES profiles,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_customers(id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations,subject text NOT NULL,email text NOT NULL,name text NOT NULL,marketing_consent boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,subject),UNIQUE(id,organization_id));
ALTER TABLE customers ADD COLUMN account_id text REFERENCES organization_customers;
CREATE TABLE site_documents(restaurant_id text PRIMARY KEY REFERENCES restaurants,draft jsonb NOT NULL DEFAULT '{}',published jsonb,revision integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE site_publications(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,document jsonb NOT NULL,revision integer NOT NULL,created_by text NOT NULL REFERENCES profiles,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,revision));
CREATE TABLE site_assets(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,object_key text NOT NULL UNIQUE,content_type text NOT NULL,bytes integer NOT NULL CHECK(bytes>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE restaurant_domains(hostname text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,verification_hash text NOT NULL,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_placements(organization_id text PRIMARY KEY REFERENCES organizations,cluster_key text NOT NULL DEFAULT 'primary',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integration_connections(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,kind text NOT NULL CHECK(kind IN ('cash_register','payment','accounting','payroll','delivery')),provider text NOT NULL,status text NOT NULL DEFAULT 'unconfigured' CHECK(status IN ('unconfigured','testing','validated','disabled')),secret_ciphertext text,validation_evidence text,UNIQUE(restaurant_id,kind,provider));
CREATE TABLE outbox_jobs(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,kind text NOT NULL,payload jsonb NOT NULL,dedupe_key text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','done','failed')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),locked_until timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(restaurant_id,kind,dedupe_key));
CREATE INDEX jobs_due ON outbox_jobs(available_at) WHERE status IN ('pending','running');
CREATE TABLE restaurant_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,event_type text NOT NULL,resource_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_scope ON restaurant_events(restaurant_id,sequence);
CREATE TABLE rate_limits(bucket text PRIMARY KEY,hits integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE offline_devices(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,profile_id text NOT NULL REFERENCES profiles,name text NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE offline_quotas(id text PRIMARY KEY,device_id text NOT NULL REFERENCES offline_devices,menu_id text NOT NULL REFERENCES menu_items,quantity integer NOT NULL CHECK(quantity>0),used integer NOT NULL DEFAULT 0 CHECK(used>=0 AND used<=quantity),catalog jsonb NOT NULL,status text NOT NULL DEFAULT 'allocated' CHECK(status IN ('allocated','reconciled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE offline_allocations(id text PRIMARY KEY,quota_id text NOT NULL REFERENCES offline_quotas,lot_id text NOT NULL REFERENCES stock_lots,quantity numeric NOT NULL CHECK(quantity>0),consumed numeric NOT NULL DEFAULT 0 CHECK(consumed>=0 AND consumed<=quantity));
CREATE TABLE offline_operations(id text PRIMARY KEY,device_id text NOT NULL REFERENCES offline_devices,payload jsonb NOT NULL,payload_hash text NOT NULL,status text NOT NULL CHECK(status IN ('applied','conflict')),order_id text REFERENCES orders,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_sessions(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','applied','cancelled')),created_by text NOT NULL REFERENCES profiles,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_lines(session_id text NOT NULL REFERENCES inventory_sessions,lot_id text NOT NULL REFERENCES stock_lots,counted numeric NOT NULL CHECK(counted>=0),PRIMARY KEY(session_id,lot_id));
CREATE TABLE purchase_documents(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,supplier_id text NOT NULL REFERENCES suppliers,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','confirmed','partial','received','cancelled')),due_on date NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_document_lines(id text PRIMARY KEY,document_id text NOT NULL REFERENCES purchase_documents,ingredient_id text NOT NULL REFERENCES ingredients,quantity numeric NOT NULL CHECK(quantity>0),received numeric NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity));
CREATE TABLE option_recipes(menu_id text NOT NULL REFERENCES menu_items,choice_id text NOT NULL,ingredient_id text NOT NULL REFERENCES ingredients,quantity numeric NOT NULL CHECK(quantity>0),PRIMARY KEY(menu_id,choice_id,ingredient_id));
CREATE TABLE unit_conversions(restaurant_id text NOT NULL REFERENCES restaurants,from_unit text NOT NULL,to_unit text NOT NULL,factor numeric NOT NULL CHECK(factor>0),PRIMARY KEY(restaurant_id,from_unit,to_unit));
ALTER TABLE orders DROP CONSTRAINT orders_idempotency_key_key;
ALTER TABLE orders ADD CONSTRAINT orders_scoped_key UNIQUE(restaurant_id,idempotency_key);
INSERT INTO schema_versions VALUES(5);
